{
  "image_summary": "该图表展示了观众对演员吴京的评价维度在四个不同职业发展阶段（从动作演员到后战狼时期）的构成比例变化，体现了其公众形象从单一专业能力向民族国家认同的演变。",
  "chart_type": "堆叠横向柱状图",
  "title_text": "观众评价吴京的维度，发生了四个阶段的变化",
  "footer_text": "",
  "axes": {
    "x_label": "评价占比 (%)",
    "y_label": "吴京职业生涯阶段",
    "x_categories": [],
    "y_range_or_categories": [
      "1 动作演员与军旅角色",
      "2 “战狼” IP成型",
      "3 国家工业大片扩张",
      "4 后“战狼”分化"
    ]
  },
  "series": [
    {
      "name": "专业能力",
      "color": "#fc8166",
      "data_points": [["1 动作演员与军旅角色", 86.1], ["2 “战狼” IP成型", 34.0], ["3 国家工业大片扩张", 55.4], ["4 后“战狼”分化", 75.6]],
      "meaning": "观众基于演技、动作设计等专业维度的评价占比"
    },
    {
      "name": "道德人格",
      "color": "#7dd3f9",
      "data_points": [["1 动作演员与军旅角色", 0], ["2 “战狼” IP成型", 2.1], ["3 国家工业大片扩张", 3.0], ["4 后“战狼”分化", 4.0]],
      "meaning": "观众基于个人品德、私生活等维度的评价占比（图中未明确标注数值，根据视觉估算）"
    },
    {
      "name": "民族国家",
      "color": "#e74c3c",
      "data_points": [["1 动作演员与军旅角色", 9.2], ["2 “战狼” IP成型", 46.6], ["3 国家工业大片扩张", 37.7], ["4 后“战狼”分化", 16.1]],
      "meaning": "观众基于爱国情怀、国家形象等维度的评价占比"
    },
    {
      "name": "商业资本",
      "color": "#f39c12",
      "data_points": [["1 动作演员与军旅角色", 0], ["2 “战狼” IP成型", 6.7], ["3 国家工业大片扩张", 2.5], ["4 后“战狼”分化", 2.5]],
      "meaning": "观众基于票房号召力、商业价值等维度的评价占比（部分为视觉估算）"
    },
    {
      "name": "社会文化/性别",
      "color": "#a569bd",
      "data_points": [["1 动作演员与军旅角色", 4.7], ["2 “战狼” IP成型", 10.6], ["3 国家工业大片扩张", 1.4], ["4 后“战狼”分化", 1.8]],
      "meaning": "观众基于社会文化影响、男性气质等维度的评价占比（部分为视觉估算）"
    }
  ],
  "table_data": {
    "headers": ["阶段", "专业能力", "道德人格", "民族国家", "商业资本", "社会文化/性别"],
    "rows": [
      ["1 动作演员与军旅角色", "86.1%", "-", "9.2%", "-", "-"],
      ["2 “战狼” IP成型", "34.0%", "-", "46.6%", "6.7%", "10.6%"],
      ["3 国家工业大片扩张", "55.4%", "-", "37.7%", "-", "-"],
      ["4 后“战狼”分化", "75.6%", "-", "16.1%", "-", "-"]
    ]
  },
  "color_encoding": [
    {"color": "橙色 #fc8166", "meaning": "专业能力"},
    {"color": "浅蓝色 #7dd3f9", "meaning": "道德人格"},
    {"color": "红色 #e74c3c", "meaning": "民族国家"},
    {"color": "橙黄色 #f39c12", "meaning": "商业资本"},
    {"color": "紫色 #a569bd", "meaning": "社会文化/性别"},
    {"color": "浅绿色 #a8d08d", "meaning": "身份符号"}
  ],
  "visualization_spec": "画布采用竖版布局（约16:9或更长），背景色为极浅的米灰色（#f5f5f5）。顶部为深灰色背景条，居中放置白色粗体大标题，其中“四个阶段”四个字使用橙色高亮。主体区域顶部排列图例，包含六个彩色方块及对应文字。下方是四行横向堆叠柱状图，每行左侧标注阶段序号和名称。柱子由左至右按图例颜色顺序堆叠，代表各维度百分比之和为100%。主要数据标签（如86.1%、46.6%）直接显示在对应颜色的色块内部，白色字体。背景中央有半透明的娱乐资本论卡通吉祥物水印。底部居中放置数据来源说明文字，最底部为深灰色页脚，居中放置娱乐资本论Logo及英文ENTERTAINMENT CAPITAL。",
  "key_data_highlights": [
    "在第一阶段，'专业能力'占据绝对主导地位（86.1%），表明早期吴京被视为纯粹的动作演员。",
    "第二阶段'战狼IP成型'时，'民族国家'维度激增至46.6%，成为核心评价标签，超过专业能力。",
    "第四阶段出现'后战狼分化'，专业能力评价回升至75.6%，而民族国家评价回落至16.1%，显示公众关注点回归演艺本身。"
  ],
  "data_source_text": "数据来源：豆瓣短评，娱乐资本论整理"
}
